static bool test_client_rpc_query(aisoc_dbus_conn_t* cli) {
    aisoc_dbus_method_call_t call = { AISOC_DBUS_BUS_NAME_FORWARD, AISOC_DBUS_PATH_FORWARD, AISOC_DBUS_IFACE_FORWARD, "TriggerQuery" };
    aisoc_dbus_msg_t req;
    aisoc_dbus_msg_init_call(&call, &req);
    aisoc_dbus_msg_append_byte(&req, 1);
    aisoc_dbus_msg_append_uint32(&req, 200);

    aisoc_dbus_call_opts_t opts = { 500, true };
    aisoc_dbus_msg_t reply;
    aisoc_dbus_status_t st = aisoc_dbus_call_method(cli, &req, &opts, &reply);
    aisoc_dbus_msg_unref(&req);
    TEST_CHECK(st == AISOC_DBUS_OK, "TriggerQuery RPC success");

    aisoc_dbus_iter_t iter;
    aisoc_dbus_iter_init(&reply, &iter);
    int32_t err_code = -1;
    uint32_t tx_id = 0;
    aisoc_dbus_iter_get_int32(&iter, &err_code);
    aisoc_dbus_iter_get_uint32(&iter, &tx_id);
    aisoc_dbus_msg_unref(&reply);

    TEST_CHECK(err_code == 0, "TriggerQuery error_code is 0");
    TEST_CHECK(tx_id == 1, "TriggerQuery transaction_id is 1");
    return true;
}

static bool test_client_rpc_port(aisoc_dbus_conn_t* cli) {
    aisoc_dbus_method_call_t call = { AISOC_DBUS_BUS_NAME_FORWARD, AISOC_DBUS_PATH_FORWARD, AISOC_DBUS_IFACE_FORWARD, "GetPortStatus" };
    aisoc_dbus_msg_t req;
    aisoc_dbus_msg_init_call(&call, &req);

    aisoc_dbus_call_opts_t opts = { 500, true };
    aisoc_dbus_msg_t reply;
    aisoc_dbus_status_t st = aisoc_dbus_call_method(cli, &req, &opts, &reply);
    aisoc_dbus_msg_unref(&req);
    TEST_CHECK(st == AISOC_DBUS_OK, "GetPortStatus RPC success");

    aisoc_dbus_iter_t iter;
    aisoc_dbus_iter_init(&reply, &iter);
    bool is_open = false;
    const char* path = nullptr;
    uint64_t tx = 0;
    uint64_t rx = 0;
    aisoc_dbus_iter_get_bool(&iter, &is_open);
    aisoc_dbus_iter_get_string(&iter, &path);
    aisoc_dbus_iter_get_uint64(&iter, &tx);
    aisoc_dbus_iter_get_uint64(&iter, &rx);

    TEST_CHECK(is_open == true, "GetPortStatus is_open");
    TEST_CHECK(path != nullptr && strcmp(path, "/dev/ttyUSB0") == 0, "GetPortStatus path");
    TEST_CHECK(tx == 1042ULL, "GetPortStatus tx");
    TEST_CHECK(rx == 1040ULL, "GetPortStatus rx");
    aisoc_dbus_msg_unref(&reply);
    return true;
}

