    aisoc_dbus_msg_append_byte(&req, 2);
    aisoc_dbus_msg_append_uint32(&req, 50); /* Triggers 100ms server sleep */

    aisoc_dbus_call_opts_t opts = { 40, true }; /* 40ms client deadline -> Timeout */
