    aisoc_dbus_msg_unref(&req);

    TEST_CHECK(st == AISOC_DBUS_ERR_TIMEOUT, "Deadline expired timeout detection");
    aisoc_dbus_msg_unref(&reply);
    return true;
}

static bool test_client_rpc_dev_and_hms(aisoc_dbus_conn_t* cli) {
