    aisoc_dbus_msg_t req;
    aisoc_dbus_msg_init_call(&call, &req);
    aisoc_dbus_msg_append_string(&req, "bed");

    aisoc_dbus_call_opts_t opts = { 500, true };
    aisoc_dbus_msg_t reply;
    aisoc_dbus_status_t st = aisoc_dbus_call_method(cli, &req, &opts, &reply);
    aisoc_dbus_msg_unref(&req);
    TEST_CHECK(st == AISOC_DBUS_OK, "RequestImmediateSample admitted");

    aisoc_dbus_iter_t iter;
    aisoc_dbus_iter_init(&reply, &iter);
    bool accepted = false;
    const char* reason = nullptr;
    aisoc_dbus_iter_get_bool(&iter, &accepted);
    aisoc_dbus_iter_get_string(&iter, &reason);
    aisoc_dbus_msg_unref(&reply);
    TEST_CHECK(accepted == true, "Sample bed admitted boolean");

    /* HMS ClearAlarm 1001 */
    aisoc_dbus_method_call_t hms_call = { AISOC_DBUS_BUS_NAME_HMS, AISOC_DBUS_PATH_HMS, AISOC_DBUS_IFACE_HMS, "ClearAlarm" };
