\\\ntypedef enum {\\\\\\\\n    AISOC_DBUS_OK                     =  0,\\\\\\\\n    AISOC_DBUS_ERR_NULL_PTR           = -1,\\\\\\\\n    AISOC_DBUS_ERR_INVALID_PARAM      = -2,\\\\\\\\n    AISOC_DBUS_ERR_DISCONNECTED       = -3,\\\\\\\\n    AISOC_DBUS_ERR_INTERNAL           = -4,\\\\\\\\n    AISOC_DBUS_ERR_DEVICE_BUSY        = -5,\\\\\\\\n    AISOC_DBUS_ERR_BUFFER_OVERFLOW    = -6,\\\\\\\\n    AISOC_DBUS_ERR_TYPE_MISMATCH      = -7,\\\\\\\\n    AISOC_DBUS_ERR_TIMEOUT            = -8,\\\\\\\\n    AISOC_DBUS_ERR_NAME_TAKEN         = -9,\\\\\\\\n    AISOC_DBUS_ERR_UNKNOWN_METHOD     = -10,\\\\\\\\n    AISOC_DBUS_ERR_NO_REPLY           = -11,\\\\\\\\n    AISOC_DBUS_ERR_CRC_MISMATCH       = -12,\\\\\\\\n    AISOC_DBUS_ERR_PERMISSION_DENIED  = -13,\\\\\\\\n    AISOC_DBUS_ERR_EMERGENCY_STOP     = -18\\\\\\\\n} aisoc_dbus_status_t;\\\\\\\\n\\\\\\\\ntypedef enum {\\\\\\\\n    AISOC_DBUS_BUS_SESSION            = 0,\\\\\\\\n    AISOC_DBUS_BUS_SYSTEM             = 1,\\\\\\\\n    AISOC_DBUS_BUS_CUSTOM             = 2\\\\\\\\n} aisoc_dbus_bus_type_t;\\\\\\\\n\\\\\\\\n/* ========================================================================= */\\\\\\\\n/* 3. Core Structures                                                        */\\\\\\\\n/* ========================================================================= */\\\\\\\\n\\\\\\\\ntypedef struct {\\\\\\\\n    int32_t     bus_type;\\\\\\\\n    const char* custom_address;\\\\\\\\n    bool        exit_on_disconnect;\\\\\\\\n} aisoc_dbus_conn_config_t;\\\\\\\\n\\\\\\\\ntypedef struct {\\\\\\\\n    DBusMessage* msg;\\\\\\\\n    int32_t      msg_type;\\\\\\\\n} aisoc_dbus_msg_t;\\\\\\\\n\\\\\\\\ntypedef struct {\\\\\\\\n    DBusMessageIter iter;\\\\\\\\n    bool            is_valid;\\\\\\\\n} aisoc_dbus_iter_t;\\\\\\\\n\\\\\\\\ntypedef struct {\\\\\\\\n    char    name[AISOC_DBUS_NAME_MAX];\\\\\\\\n    char    message[AISOC_DBUS_ERR_MSG_MAX];\\\\\\\\n    int32_t error_code;\\\\\\\\n} aisoc_dbus_error_info_t;\\\\\\\\n\\\\\\\\ntypedef struct {\\\\\\\\n    const char* destination;\\\\\\\\n    const char* path;\\\\\\\\n    const char* interface_name;\\\\\\\\n    const char* method_name;\\\\\\\\n} aisoc_dbus_method_call_t;\\\\\\\\n\\\\\\\\ntypedef struct {\\\\\\\\n    const char* path;\\\\\\\\n    const char* interface_name;\\\\\\\\n    const char* signal_name;\\\\\\\\n} aisoc_dbus_signal_desc_t;\\\\\\\\n\\\\\\\\ntypedef struct {\\\\\\\\n    int32_t timeout_ms;\\\\\\\\n    bool    require_reply;\\\\\\\\n} aisoc_dbus_call_opts_t;\\\\\\\\n\\\\\\\\n/* Callback Handler Signatures */\\\\\\\\ntypedef aisoc_dbus_status_t (*aisoc_dbus_method_handler_t)(\\\\\\\\n    const aisoc_dbus_msg_t* req,\\\\\\\\n    aisoc_dbus_msg_t*       reply,\\\\\\\\n    void*                   user_data\\\\\\\\n);\\\\\\\\n\\\\\\\\ntypedef struct {\\\\\\\\n    const char*                 method_name;\\\\\\\\n    aisoc_dbus_method_handler_t handler;\\\\\\\\n} aisoc_dbus_method_entry_t;\\\\\\\\n\\\\\\\\ntypedef struct {\\\\\\\\n    const char*               path;\\\\\\\\n    const char*               interface_name;\\\\\\\\n    aisoc_dbus_method_entry_t methods[AISOC_DBUS_MAX_METHODS_PER_IFACE];\\\\\\\\n    size_t                    method_count;\\\\\\\\n    void*                     user_data;\\\\\\\\n} aisoc_dbus_interface_entry_t;\\\\\\\\n\\\\\\\\ntypedef void (*aisoc_dbus_signal_handler_t)(\\\\\\\\n    const aisoc_dbus_msg_t* sig,\\\\\\\\n    void*                   user_data\\\\\\\\n);\\\\\\\\n\\\\\\\\ntypedef struct {\\\\\\\\n    const char*                 path;\\\\\\\\n    const char*                 interface_name;\\\\\\\\n    const char*                 signal_name;\\\\\\\\n    aisoc_dbus_signal_handler_t handler;\\\\\\\\n    void*                       user_data;\\\\\\\\n} aisoc_dbus_signal_entry_t;\\\\\\\\n\\\\\\\\ntypedef struct {\\\\\\\\n    DBusConnection*              conn;\\\\\\\\n    char                         bus_address[AISOC_DBUS_ADDR_MAX];\\\\\\\\n    char                         unique_name[64];\\\\\\\\n    bool                         is_connected;\\\\\\\\n    bool                         is_server;\\\\\\\\n    aisoc_dbus_interface_entry_t interfaces[AISOC_DBUS_MAX_INTERFACES];\\\\\\\\n    size_t                       interface_count;\\\\\\\\n    aisoc_dbus_signal_entry_t    signals[AISOC_DBUS_MAX_SIGNALS];\\\\\\\\n    size_t                       signal_count;\\\\\\\\n} aisoc_dbus_conn_t;\\\\\\\\n\\\\\\\\n/* ========================================================================= */\\\\\\\\n/* 4. Domain Specific Command and Response Types                             */\\\\\\\\n/* ========================================================================= */\\\\\\\\n\\\\\\\\n/* ForwardInterface Domain Types */\\\\\\\\ntypedef struct {\\\\\\\\n    uint8_t  target_node;\\\\\\\\n    uint32_t timeout_ms;\\\\\\\\n} aisoc_dbus_fwd_query_req_t;\\\\\\\\n\\\\\\\\ntypedef struct {\\\\\\\\n    int32_t  error_code;\\\\\\\\n    uint32_t transaction_id;\\\\\\\\n} aisoc_dbus_fwd_query_resp_t;\\\\\\\\n\\\\\\\\ntypedef struct {\\\\\\\\n    bool     is_open;\\\\\\\\n    char     port_path[64];\\\\\\\\n    uint64_t tx_count;\\\\\\\\n    uint64_t rx_count;\\\\\\\\n} aisoc_dbus_fwd_port_status_resp_t;\\\\\\\\n\\\\\\\\ntypedef struct {\\\\\\\\n    uint8_t node_id;\\\\\\\\n    bool    is_connected;\\\\\\\\n    char    reason[64];\\\\\\\\n} aisoc_dbus_fwd_link_sig_t;\\\\\\\\n\\\\\\\\n/* DeviceInterface Domain Types */\\\\\\\\ntypedef struct {\\\\\\\\n    char snapshot_json[1024];\\\\\\\\n} aisoc_dbus_dev_snapshot_resp_t;\\\\\\\\n\\\\\\\\ntypedef struct {\\\\\\\\n    char source_type[32];\\\\\\\\n} aisoc_dbus_dev_sample_req_t;\\\\\\\\n\\\\\\\\ntypedef struct {\\\\\\\\n    bool accepted;\\\\\\\\n    char reason[128];\\\\\\\\n} aisoc_dbus_dev_sample_resp_t;\\\\\\\\n\\\\\\\\ntypedef struct {\\\\\\\\n    char state_json[512];\\\\\\\\n} aisoc_dbus_dev_state_resp_t;\\\\\\\\n\\\\\\\\ntypedef struct {\\\\\\\\n    uint32_t generation_id;\\\\\\\\n    uint64_t timestamp_ns;\\\\\\\\n} aisoc_dbus_dev_snapshot_sig_t;\\\\\\\\n\\\\\\\\ntypedef struct {\\\\\\\\n    char old_state[32];\\\\\\\\n    char new_state[32];\\\\\\\\n    char reason[128];\\\\\\\\n} aisoc_dbus_dev_state_sig_t;\\\\\\\\n\\\\\\\\n/* HmsInterface Domain Types */\\\\\\\\ntypedef struct {\\\\\\\\n    char alarms_json[1024];\\\\\\\\n} aisoc_dbus_hms_alarms_resp_t;\\\\\\\\n\\\\\\\\ntypedef struct {\\\\\\\\n    uint32_t alarm_id;\\\\\\\\n<!--\\\\\\\\n  D-Bus Session Bus Configuration for VMware & Desktop Twin Environment\\\\\\\\n  Task ID: TWIN-06\\\\\\\\n  Interface Specification: ICD-VMWARE-SOC-TWIN-20261029 / dbus_interfaces.xml\\\\\\\\n-->\\\\\\\\n<!DOCTYPE busconfig PUBLIC \\\\\\\\\\\\\\\"-//freedesktop//DTD D-Bus Bus Configuration 1.0//EN\\\\\\\\\\\\\\\"\\\\\\\\n \\\\\\\\\\\\\\\"http://www.freedesktop.org/standards/dbus/1.0/busconfig.dtd\\\\\\\\\\\\\\\">\\\\\\\\n<busconfig>\\\\\\\\n  <type>session</type>\\\\\\\\n  <listen>unix:tmpdir=/tmp</listen>\\\\\\\\n  <auth>EXTERNAL</auth>\\\\\\\\n\\\\\\\\n  <!-- Default Security and Routing Policy: Strict Whitelist Only -->\\\\\\\\n  <policy context=\\\\\\\\\\\\\\\"default\\\\\\\\\\\\\\\">\\\\\\\\n    <!-- Deny owning any service name by default -->\\\\\\\\n    <deny own=\\\\\\\\\\\\\\\"*\\\\\\\\\\\\\\\"/>\\\\\\\\n    <deny send_type=\\\\\\\\\\\\\\\"method_call\\\\\\\\\\\\\\\"/>\\\\\\\\n\\\\\\\\n    <!-- Allow method returns and errors for requested calls -->\\\\\\\\n    <allow send_requested_reply=\\\\\\\\\\\\\\\"true\\\\\\\\\\\\\\\" send_type=\\\\\\\\\\\\\\\"method_return\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow send_requested_reply=\\\\\\\\\\\\\\\"true\\\\\\\\\\\\\\\" send_type=\\\\\\\\\\\\\\\"error\\\\\\\\\\\\\\\"/>\\\\\\\\n\\\\\\\\n    <!-- Allow reception of replies and signals -->\\\\\\\\n    <allow receive_type=\\\\\\\\\\\\\\\"method_call\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow receive_type=\\\\\\\\\\\\\\\"method_return\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow receive_type=\\\\\\\\\\\\\\\"error\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow receive_type=\\\\\\\\\\\\\\\"signal\\\\\\\\\\\\\\\"/>\\\\\\\\n\\\\\\\\n    <!-- Explicitly allow owning org.aisoc.* service names -->\\\\\\\\n    <allow own=\\\\\\\\\\\\\\\"org.aisoc.Forward\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow own=\\\\\\\\\\\\\\\"org.aisoc.Device\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow own=\\\\\\\\\\\\\\\"org.aisoc.Hms\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow own=\\\\\\\\\\\\\\\"org.aisoc.UiGateway\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow own=\\\\\\\\\\\\\\\"org.aisoc.JobEngine\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow own=\\\\\\\\\\\\\\\"org.aisoc.StorageService\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow own_prefix=\\\\\\\\\\\\\\\"org.aisoc\\\\\\\\\\\\\\\"/>\\\\\\\\n\\\\\\\\n    <!-- Allow method calls and signals to known twin services -->\\\\\\\\n    <allow send_destination=\\\\\\\\\\\\\\\"org.aisoc.Forward\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow send_destination=\\\\\\\\\\\\\\\"org.aisoc.Device\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow send_destination=\\\\\\\\\\\\\\\"org.aisoc.Hms\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow send_destination=\\\\\\\\\\\\\\\"org.aisoc.UiGateway\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow send_destination=\\\\\\\\\\\\\\\"org.aisoc.JobEngine\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow send_destination=\\\\\\\\\\\\\\\"org.aisoc.StorageService\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow send_destination=\\\\\\\\\\\\\\\"org.freedesktop.DBus\\\\\\\\\\\\\\\"/>\\\\\\\\n\\\\\\\\n    <allow send_interface=\\\\\\\\\\\\\\\"org.aisoc.ForwardInterface\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow send_interface=\\\\\\\\\\\\\\\"org.aisoc.DeviceInterface\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow send_interface=\\\\\\\\\\\\\\\"org.aisoc.HmsInterface\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow send_interface=\\\\\\\\\\\\\\\"org.freedesktop.DBus.Introspectable\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow send_interface=\\\\\\\\\\\\\\\"org.freedesktop.DBus\\\\\\\\\\\\\\\"/>\\\\\\\\n  </policy>\\\\\\\\n\\\\\\\\n  <!-- Include system security policy if present -->\\\\\\\\n  <include ignore_missing=\\\\\\\\\\\\\\\"yes\\\\\\\\\\\\\\\">org.aisoc.conf</include>\\\\\\\\n\\\\\\\\n  <!-- Resource Limits for Embedded Twin Validation -->\\\\\\\\n  <limit name=\\\\\\\\\\\\\\\"max_completed_connections\\\\\\\\\\\\\\\">256</limit>\\\\\\\\n  <limit name=\\\\\\\\\\\\\\\"max_incomplete_connections\\\\\\\\\\\\\\\">64</limit>\\\\\\\\n  <limit name=\\\\\\\\\\\\\\\"max_connections_per_user\\\\\\\\\\\\\\\">128</limit>\\\\\\\\n  <limit name=\\\\\\\\\\\\\\\"max_match_rules_per_connection\\\\\\\\\\\\\\\">512</limit>\\\\\\\\n  <limit name=\\\\\\\\\\\\\\\"max_names_per_connection\\\\\\\\\\\\\\\">64</limit>\\\\\\\\n</busconfig>\\\\\\\\n<!--\\\\\\\\n  D-Bus Security and Ownership Policy for org.aisoc.* Services\\\\\\\\n  Task ID: TWIN-06\\\\\\\\n  Specification: ICD-VMWARE-SOC-TWIN-20261029 / dbus_interfaces.xml\\\\\\\\n-->\\\\\\\\n<!DOCTYPE busconfig PUBLIC \\\\\\\\\\\\\\\"-//freedesktop//DTD D-Bus Bus Configuration 1.0//EN\\\\\\\\\\\\\\\"\\\\\\\\n \\\\\\\\\\\\\\\"http://www.freedesktop.org/standards/dbus/1.0/busconfig.dtd\\\\\\\\\\\\\\\">\\\\\\\\n<busconfig>\\\\\\\\n  <!-- Default context permissions for twin environment and system bus deployment -->\\\\\\\\n  <policy context=\\\\\\\\\\\\\\\"default\\\\\\\\\\\\\\\">\\\\\\\\n    <!-- Service Name Ownership -->\\\\\\\\n    <allow own=\\\\\\\\\\\\\\\"org.aisoc.Forward\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow own=\\\\\\\\\\\\\\\"org.aisoc.Device\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow own=\\\\\\\\\\\\\\\"org.aisoc.Hms\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow own=\\\\\\\\\\\\\\\"org.aisoc.UiGateway\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow own=\\\\\\\\\\\\\\\"org.aisoc.JobEngine\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow own=\\\\\\\\\\\\\\\"org.aisoc.StorageService\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow own_prefix=\\\\\\\\\\\\\\\"org.aisoc\\\\\\\\\\\\\\\"/>\\\\\\\\n\\\\\\\\n    <!-- Client Invocations to org.aisoc Services -->\\\\\\\\n    <allow send_destination=\\\\\\\\\\\\\\\"org.aisoc.Forward\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow send_destination=\\\\\\\\\\\\\\\"org.aisoc.Device\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow send_destination=\\\\\\\\\\\\\\\"org.aisoc.Hms\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow send_destination=\\\\\\\\\\\\\\\"org.aisoc.UiGateway\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow send_destination=\\\\\\\\\\\\\\\"org.aisoc.JobEngine\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow send_destination=\\\\\\\\\\\\\\\"org.aisoc.StorageService\\\\\\\\\\\\\\\"/>\\\\\\\\n\\\\\\\\n    <!-- Interface Invocations -->\\\\\\\\n    <allow send_interface=\\\\\\\\\\\\\\\"org.aisoc.ForwardInterface\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow send_interface=\\\\\\\\\\\\\\\"org.aisoc.DeviceInterface\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow send_interface=\\\\\\\\\\\\\\\"org.aisoc.HmsInterface\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow send_interface=\\\\\\\\\\\\\\\"org.freedesktop.DBus.Introspectable\\\\\\\\\\\\\\\"/>\\\\\\\\n\\\\\\\\n    <!-- Receive Replies and Signals -->\\\\\\\\n    <allow receive_sender=\\\\\\\\\\\\\\\"org.aisoc.Forward\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow receive_sender=\\\\\\\\\\\\\\\"org.aisoc.Device\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow receive_sender=\\\\\\\\\\\\\\\"org.aisoc.Hms\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow receive_sender=\\\\\\\\\\\\\\\"org.aisoc.UiGateway\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow receive_sender=\\\\\\\\\\\\\\\"org.aisoc.JobEngine\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow receive_sender=\\\\\\\\\\\\\\\"org.aisoc.StorageService\\\\\\\\\\\\\\\"/>\\\\\\\\n\\\\\\\\n    <allow receive_interface=\\\\\\\\\\\\\\\"org.aisoc.ForwardInterface\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow receive_interface=\\\\\\\\\\\\\\\"org.aisoc.DeviceInterface\\\\\\\\\\\\\\\"/>\\\\\\\\n    <allow receive_interface=\\\\\\\\\\\\\\\"org.aisoc.HmsInterface\\\\\\\\\\\\\\\"/>\\\\\\\\n  </policy>\\\\\\\\n</busconfig>\\\\\\\\n# AI-SoC D-Bus 跨进程通信中间件 SDK (aisoc_dbus)\\\\\\\\n\\\\\\\\n| 属性 | 规格 / 取值 |\\\\\\\\n| :--- | :--- |\\\\\\\\n| **模块维护 Owner** | ENG-DBUS (D-Bus 通信工程师) |\\\\\\\\n| **对应实现任务** | TWIN-06 / TASK-015 |\\\\\\\\n| **契约规范源** | `soc-ap/contracts/twin/dbus_interfaces.xml` (v2.0) |\\\\\\\\n| **依赖库版本** | `libdbus-1.so` (D-Bus 1.16.2) |\\\\\\\\n| **编码标准约束** | 严禁超 50 行函数、严禁超 4 入参、零无界堆分配、禁用异常与 RTTI (`-fno-exceptions -fno-rtti`) |\\\\\\\\n\\\\\\\\n---\\\\\\\\n\\\\\\\\n## 1. 模块架构与职责定位\\\\\\\\n\\\\\\\\n`aisoc_dbus` 是 SoC-AP 端跨进程控制与准入的基础统一 SDK，向上层业务（`forward-service` 串口路由、`device-manager` 状态权威机、`hms-service` 硬件诊断等）提供高可靠、带强类型防御的 RPC 与信号通信机制：\\\\\\\\n\\\\\\\\n```text\\\\\\\\n               +-------------------------------------------+\\\\\\\\n               |        SoC-AP 业务微服务 (C/C++)          |\\\\\\\\n               | (ForwardService, DeviceManager, Hms, ...) |\\\\\\\\n               +-------------------------------------------+\\\\\\\\n                                     │\\\\\\\\n           [aisoc_dbus.h]            ▼\\\\\\\\n   ┌───────────────────────────────────────────────────────────┐\\\\\\\\n   │                  aisoc_dbus 统一 SDK 核心                 │\\\\\\\\n   │  ├─ aisoc_dbus_core:   总线生命周期、名称申请/释放、心跳  │\\\\\\\\n   │  ├─ aisoc_dbus_msg:    消息构造、序列化、迭代器、错误映射 │\\\\\\\\n   │  ├─ aisoc_dbus_client: 同步 RPC 调用、超时控制、错误拦截 │\\\\\\\\n   │  └─ aisoc_dbus_server: 对象路径注册、方法分发、信号广播   │\\\\\\\\n   └───────────────────────────────────────────────────────────┘\\\\\\\\n                                     │\\\\\\\\n                                     ▼\\\\\\\\n           +───────────────────────────────────────────────────+\\\\\\\\n           |        libdbus-1 (third_party/install/lib)        |\\\\\\\\n           +───────────────────────────────────────────────────+\\\\\\\\n                                     │\\\\\\\\n                                     ▼\\\\\\\\n           +───────────────────────────────────────────────────+\\\\\\\\n           |      D-Bus Daemon (session / twin bus socket)     |\\\\\\\\n           +───────────────────────────────────────────────────+\\\\\\\\n```\\\\\\\\n\\\\\\\\n---\\\\\\\\n\\\\\\\\n## 2. 核心设计与代码硬门禁规范\\\\\\\\n\\\\\\\\n1. **自研函数双硬门禁**：\\\\\\\\n   - **函数行数 $\\\\\\\\\\\\\\\\le 50$ 行**：所有内部逻辑均拆解为带 `static` 修饰的专用处理步进函数。\\\\\\\\n   - **函数入参 $\\\\\\\\\\\\\\\\le 4$ 个**：复杂参数均封装为专用上下文或请求/响应结构体指针。\\\\\\\\n2. **指针与内存安全**：\\\\\\\\n   - 公开 API 首行强制执行防御性空指针校验（Guard Clause），指针非法直接返回 `AISOC_DBUS_ERR_NULL_PTR`。\\\\\\\\n   - 入参在前、出参在后，只读入参必须加 `const`。\\\\\\\\n   - 指针解引用独立成行，杜绝 `*p++` 运算合并；禁用三级及以上指针。\\\\\\\\n   - 包装层逻辑杜绝无界堆分配，使用栈与定长缓冲区，全面兼容 `-fno-exceptions -fno-rtti`。\\\\\\\\n3. **统一错误码转换**：\\\\\\\\n   - SDK 统一度量为 `aisoc_dbus_status_t` 枚举。\\\\\\\\n   - 自动与权威契约中的标准 D-Bus 错误名双向互转：\\\\\\\\n     - `org.aisoc.Error.None` $\\\\\\\\\\\\\\\\longleftrightarrow$ `AISOC_DBUS_OK` (0)\\\\\\\\n     - `org.aisoc.Error.Timeout` $\\\\\\\\\\\\\\\\longleftrightarrow$ `AISOC_DBUS_ERR_TIMEOUT` (-8)\\\\\\\\n     - `org.aisoc.Error.InvalidArgument` $\\\\\\\\\\\\\\\\longleftrightarrow$ `AISOC_DBUS_ERR_INVALID_PARAM` (-2)\\\\\\\\n     - `org.aisoc.Error.DeviceBusy` $\\\\\\\\\\\\\\\\longleftrightarrow$ `AISOC_DBUS_ERR_DEVICE_BUSY` (-5)\\\\\\\\n     - `org.aisoc.Error.CrcMismatch` $\\\\\\\\\\\\\\\\longleftrightarrow$ `AISOC_DBUS_ERR_CRC_MISMATCH` (-12)\\\\\\\\n     - `org.aisoc.Error.EmergencyStopped` $\\\\\\\\\\\\\\\\longleftrightarrow$ `AISOC_DBUS_ERR_EMERGENCY_STOP` (-18)\\\\\\\\n     - `org.aisoc.Error.Disconnected` $\\\\\\\\\\\\\\\\longleftrightarrow$ `AISOC_DBUS_ERR_DISCONNECTED` (-3)\\\\\\\\n     - `org.aisoc.Error.PermissionDenied` $\\\\\\\\\\\\\\\\longleftrightarrow$ `AISOC_DBUS_ERR_PERMISSION_DENIED` (-13)\\\\\\\\n\\\\\\\\n---\\\\\\\\n\\\\\\\\n## 3. 公开 API 快速参考\\\\\\\\n\\\\\\\\n```c\\\\\\\\n#include \\\\\\\\\\\\\\\"aisoc_dbus.h\\\\\\\\\\\\\\\"\\\\\\\\n\\\\\\\\n// 1. 初始化连接\\\\\\\\naisoc_dbus_conn_config_t cfg;\\\\\\\\ncfg.bus_type = AISOC_DBUS_BUS_SESSION;\\\\\\\\ncfg.custom_address = nullptr; // 或指定 unix:path=...\\\\\\\\ncfg.exit_on_disconnect = false;\\\\\\\\n\\\\\\\\naisoc_dbus_conn_t conn;\\\\\\\\naisoc_dbus_conn_init(&cfg, &conn);\\\\\\\\n\\\\\\\\n// 2. 服务端：申请知名总线名称并注册接口\\\\\\\\naisoc_dbus_request_name(&conn, \\\\\\\\\\\\\\\"org.aisoc.Forward\\\\\\\\\\\\\\\", true);\\\\\\\\n\\\\\\\\naisoc_dbus_interface_entry_t iface;\\\\\\\\niface.path = \\\\\\\\\\\\\\\"/org/aisoc/forward\\\\\\\\\\\\\\\";\\\\\\\\niface.interface_name = \\\\\\\\\\\\\\\"org.aisoc.ForwardInterface\\\\\\\\\\\\\\\";\\\\\\\\niface.method_count = 1;\\\\\\\\niface.methods[0].method_name = \\\\\\\\\\\\\\\"TriggerQuery\\\\\\\\\\\\\\\";\\\\\\\\niface.methods[0].handler = my_handler;\\\\\\\\niface.user_data = nullptr;\\\\\\\\naisoc_dbus_register_interface(&conn, &iface);\\\\\\\\n\\\\\\\\n// 3. 客户端：调用 RPC 方法（带超时）\\\\\\\\naisoc_dbus_method_call_t call;\\\\\\\\ncall.destination = \\\\\\\\\\\\\\\"org.aisoc.Forward\\\\\\\\\\\\\\\";\\\\\\\\ncall.path = \\\\\\\\\\\\\\\"/org/aisoc/forward\\\\\\\\\\\\\\\";\\\\\\\\ncall.interface_name = \\\\\\\\\\\\\\\"org.aisoc.ForwardInterface\\\\\\\\\\\\\\\";\\\\\\\\ncall.method_name = \\\\\\\\\\\\\\\"TriggerQuery\\\\\\\\\\\\\\\";\\\\\\\\n\\\\\\\\naisoc_dbus_msg_t req;\\\\\\\\naisoc_dbus_msg_init_call(&call, &req);\\\\\\\\naisoc_dbus_msg_append_byte(&req, 1);\\\\\\\\naisoc_dbus_msg_append_uint32(&req, 200);\\\\\\\\n\\\\\\\\naisoc_dbus_call_opts_t opts = { 500, true };\\\\\\\\naisoc_dbus_msg_t reply;\\\\\\\\naisoc_dbus_status_t st = aisoc_dbus_call_method(&conn, &req, &opts, &reply);\\\\\\\\n\\\\\\\\n// 4. 信号广播\\\\\\\\naisoc_dbus_signal_desc_t sig_desc = { \\\\\\\\\\\\\\\"/org/aisoc/forward\\\\\\\\\\\\\\\", \\\\\\\\\\\\\\\"org.aisoc.ForwardInterface\\\\\\\\\\\\\\\", \\\\\\\\\\\\\\\"LinkStateChanged\\\\\\\\\\\\\\\" };\\\\\\\\naisoc_dbus_msg_t sig_msg;\\\\\\\\naisoc_dbus_msg_init_signal(&sig_desc, &sig_msg);\\\\\\\\naisoc_dbus_msg_append_byte(&sig_msg, 1);\\\\\\\\naisoc_dbus_msg_append_bool(&sig_msg, true);\\\\\\\\naisoc_dbus_msg_append_string(&sig_msg, \\\\\\\\\\\\\\\"INITIAL_HANDSHAKE_OK\\\\\\\\\\\\\\\");\\\\\\\\naisoc_dbus_send_message(&conn, &sig_msg);\\\\\\\\naisoc_dbus_msg_unref(&sig_msg);\\\\\\\\n\\\\\\\\n// 5. 信号订阅与事件循环\\\\\\\\naisoc_dbus_signal_entry_t sig_sub;\\\\\\\\nsig_sub.path = \\\\\\\\\\\\\\\"/org/aisoc/forward\\\\\\\\\\\\\\\";\\\\\\\\nsig_sub.interface_name = \\\\\\\\\\\\\\\"org.aisoc.ForwardInterface\\\\\\\\\\\\\\\";\\\\\\\\nsig_sub.signal_name = \\\\\\\\\\\\\\\"LinkStateChanged\\\\\\\\\\\\\\\";\\\\\\\\nsig_sub.handler = my_signal_cb;\\\\\\\\nsig_sub.user_data = nullptr;\\\\\\\\naisoc_dbus_subscribe_signal(&conn, &sig_sub);\\\\\\\\n\\\\\\\\nbool dispatched = false;\\\\\\\\naisoc_dbus_dispatch_once(&conn, 100, &dispatched);\\\\\\\\n\\\\\\\\n// 6. 关闭连接\\\\\\\\naisoc_dbus_conn_close(&conn);\\\\\\\\n```\\\\\\\\n\\\\\\\\n---\\\\\\\\n\\\\\\\\n## 4. 构建与测试说明\\\\\\\\n\\\\\\\\n```bash\\\\\\\\n# 1. 创建并进入构建目录\\\\\\\\nmkdir -p soc-ap/middleware/dbus/build\\\\\\\\ncd soc-ap/middleware/dbus/build\\\\\\\\n\\\\\\\\n# 2. 配置 CMake\\\\\\\\ncmake ..\\\\\\\\n\\\\\\\\n# 3. 编译 SDK 静态库、示例及测试套件\\\\\\\\nmake -j$(nproc)\\\\\\\\n\\\\\\\\n# 4. 执行测试用例\\\\\\\\n./test_dbus_ipc\\\\\\\\n```\\\\\\\\n\\\\\\\",\\\\\\\"exit_code\\\\\\\":0,\\\\\\\"status\\\\\\\":\\\\\\\"completed\\\\\\\"}}\\\\n{\\\\\\\"type\\\\\\\":\\\\\\\"item.started\\\\\\\",\\\\\\\"item\\\\\\\":{\\\\\\\"id\\\\\\\":\\\\\\\"item_8\\\\\\\",\\\\\\\"type\\\\\\\":\\\\\\\"command_execution\\\\\\\",\\\\\\\"command\\\\\\\":\\\\\\\"/bin/bash -lc \\\\\\\\\\\\\\\"git -C soc-ap show 0e3931fc2597a44cf5789cd4ff21418b228d88dd:tests/dbus/twin/test_dbus_ipc.cpp | sed -n '1,300p'; git -C soc-ap show 0e3931fc2597a44cf5789cd4ff21418b228d88dd:middleware/dbus/src/aisoc_dbus_core.cpp | sed -n '1,260p'; git -C soc-ap show 0e3931fc2597a44cf5789cd4ff21418b228d88dd:middleware/dbus/src/aisoc_dbus_server.cpp | sed -n '1,260p'\\\\\\\\\\\\\\\"\\\\\\\",\\\\\\\"aggregated_output\\\\\\\":\\\\\\\"\\\\\\\",\\\\\\\"exit_code\\\\\\\":null,\\\\\\\"status\\\\\\\":\\\\\\\"in_progress\\\\\\\"}}\\\\n{\\\\\\\"type\\\\\\\":\\\\\\\"item.completed\\\\\\\",\\\\\\\"item\\\\\\\":{\\\\\\\"id\\\\\\\":\\\\\\\"item_8\\\\\\\",\\\\\\\"type\\\\\\\":\\\\\\\"command_execution\\\\\\\",\\\\\\\"command\\\\\\\":\\\\\\\"/bin/bash -lc \\\\\\\\\\\\\\\"git -C soc-ap show 0e3931fc2597a44cf5789cd4ff21418b228d88dd:tests/dbus/twin/test_dbus_ipc.cpp | sed -n '1,300p'; git -C soc-ap show 0e3931fc2597a44cf5789cd4ff21418b228d88dd:middleware/dbus/src/aisoc_dbus_core.cpp | sed -n '1,260p'; git -C soc-ap show 0e3931fc2597a44cf5789cd4ff21418b228d88dd:middleware/dbus/src/aisoc_dbus_server.cpp | sed -n '1,260p'\\\\\\\\\\\\\\\"\\\\\\\",\\\\\\\"aggregated_output\\\\\\\":\\\\\\\"/**\\\\\\\\n * @file test_dbus_ipc.cpp\\\\\\\\n * @brief Multi-Process Integration Test Suite for D-Bus IPC SDK\\\\\\\\n * @details Conforms to:\\\\\\\\n *          - ICD-VMWARE-SOC-TWIN-20261029 (Rev 2)\\\\\\\\n *          - golden_dbus_cases.json\\\\\\\\n *          - dbus_interfaces.xml (v2.0)\\\\\\\\n *          - project-control/.agents/rules/c_cpp_coding_standard.md\\\\\\\\n * Task ID: TWIN-06\\\\\\\\n * Role: ENG-DBUS\\\\\\\\n */\\\\\\\\n\\\\\\\\n#include \\\\\\\\\\\\\\\"aisoc_dbus.h\\\\\\\\\\\\\\\"\\\\\\\\n#include <atomic>\\\\\\\\n#include <cassert>\\\\\\\\n#include <chrono>\\\\\\\\n#include <cstdio>\\\\\\\\n#include <cstdlib>\\\\\\\\n#include <cstring>\\\\\\\\n#include <signal.h>\\\\\\\\n#include <sys/wait.h>\\\\\\\\n#include <thread>\\\\\\\\n#include <unistd.h>\\\\\\\\n\\\\\\\\nstatic uint32_t g_tests_passed = 0;\\\\\\\\nstatic uint32_t g_tests_failed = 0;\\\\\\\\nstatic volatile bool g_server_running = true;\\\\\\\\n\\\\\\\\ntypedef struct {\\\\\\\\n    bool     fwd_sig_received;\\\\\\\\n    uint8_t  fwd_node_id;\\\\\\\\n    bool     fwd_connected;\\\\\\\\n    char     fwd_reason[64];\\\\\\\\n    bool     dev_sig_received;\\\\\\\\n    uint32_t dev_gen_id;\\\\\\\\n    uint64_t dev_timestamp_ns;\\\\\\\\n    bool     hms_sig_received;\\\\\\\\n    uint32_t hms_alarm_id;\\\\\\\\n    uint8_t  hms_node_id;\\\\\\\\n    uint32_t hms_err_code;\\\\\\\\n    char     hms_severity[32];\\\\\\\\n    char     hms_message[128];\\\\\\\\n} test_capture_state_t;\\\\\\\\n\\\\\\\\nstatic test_capture_state_t g_capture;\\\\\\\\n\\\\\\\\n#define TEST_CHECK(cond, msg) \\\\\\\\\\\\\\\\\\\\\\\\n    do { \\\\\\\\\\\\\\\\\\\\\\\\n        if (!(cond)) { \\\\\\\\\\\\\\\\\\\\\\\\n            printf(\\\\\\\\\\\\\\\"  [FAIL] %s:%d: %s\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\", __FILE__, __LINE__, msg); \\\\\\\\\\\\\\\\\\\\\\\\n            g_tests_failed++; \\\\\\\\\\\\\\\\\\\\\\\\n            return false; \\\\\\\\\\\\\\\\\\\\\\\\n        } \\\\\\\\\\\\\\\\\\\\\\\\n    } while (0)\\\\\\\\n\\\\\\\\n#define TEST_STEP(fn) \\\\\\\\\\\\\\\\\\\\\\\\n    do { \\\\\\\\\\\\\\\\\\\\\\\\n        printf(\\\\\\\\\\\\\\\"[RUN ] %s\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\", #fn); \\\\\\\\\\\\\\\\\\\\\\\\n        if (fn()) { \\\\\\\\\\\\\\\\\\\\\\\\n            printf(\\\\\\\\\\\\\\\"[PASS] %s\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\", #fn); \\\\\\\\\\\\\\\\\\\\\\\\n            g_tests_passed++; \\\\\\\\\\\\\\\\\\\\\\\\n        } else { \\\\\\\\\\\\\\\\\\\\\\\\n            printf(\\\\\\\\\\\\\\\"[FAIL] %s\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\", #fn); \\\\\\\\\\\\\\\\\\\\\\\\n        } \\\\\\\\\\\\\\\\\\\\\\\\n    } while (0)\\\\\\\\n\\\\\\\\n/* ========================================================================= */\\\\\\\\n/* 1. Unit Tests: Guard Clauses                                              */\\\\\\\\n/* ========================================================================= */\\\\\\\\n\\\\\\\\nstatic bool test_guard_conn() {\\\\\\\\n    aisoc_dbus_status_t st = aisoc_dbus_conn_init(nullptr, nullptr);\\\\\\\\n    TEST_CHECK(st == AISOC_DBUS_ERR_NULL_PTR, \\\\\\\\\\\\\\\"conn_init null check\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\n    st = aisoc_dbus_conn_close(nullptr);\\\\\\\\n    TEST_CHECK(st == AISOC_DBUS_ERR_NULL_PTR, \\\\\\\\\\\\\\\"conn_close null check\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\n    st = aisoc_dbus_request_name(nullptr, \\\\\\\\\\\\\\\"test.name\\\\\\\\\\\\\\\", false);\\\\\\\\n    TEST_CHECK(st == AISOC_DBUS_ERR_NULL_PTR, \\\\\\\\\\\\\\\"request_name conn null check\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\n    aisoc_dbus_conn_t dummy_conn;\\\\\\\\n    memset(&dummy_conn, 0, sizeof(dummy_conn));\\\\\\\\n    st = aisoc_dbus_request_name(&dummy_conn, nullptr, false);\\\\\\\\n    TEST_CHECK(st == AISOC_DBUS_ERR_NULL_PTR, \\\\\\\\\\\\\\\"request_name name null check\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\n    st = aisoc_dbus_release_name(nullptr, \\\\\\\\\\\\\\\"test.name\\\\\\\\\\\\\\\");\\\\\\\\n    TEST_CHECK(st == AISOC_DBUS_ERR_NULL_PTR, \\\\\\\\\\\\\\\"release_name conn null check\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\n    st = aisoc_dbus_is_connected(nullptr, nullptr);\\\\\\\\n    TEST_CHECK(st == AISOC_DBUS_ERR_NULL_PTR, \\\\\\\\\\\\\\\"is_connected null check\\\\\\\\\\\\\\\");\\\\\\\\n    return true;\\\\\\\\n}\\\\\\\\n\\\\\\\\nstatic bool test_guard_msg() {\\\\\\\\n    aisoc_dbus_status_t st = aisoc_dbus_msg_init_call(nullptr, nullptr);\\\\\\\\n    TEST_CHECK(st == AISOC_DBUS_ERR_NULL_PTR, \\\\\\\\\\\\\\\"msg_init_call null check\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\n    st = aisoc_dbus_msg_init_signal(nullptr, nullptr);\\\\\\\\n    TEST_CHECK(st == AISOC_DBUS_ERR_NULL_PTR, \\\\\\\\\\\\\\\"msg_init_signal null check\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\n    st = aisoc_dbus_msg_init_reply(nullptr, nullptr);\\\\\\\\n    TEST_CHECK(st == AISOC_DBUS_ERR_NULL_PTR, \\\\\\\\\\\\\\\"msg_init_reply null check\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\n    st = aisoc_dbus_msg_init_error(nullptr, nullptr, nullptr, nullptr);\\\\\\\\n    TEST_CHECK(st == AISOC_DBUS_ERR_NULL_PTR, \\\\\\\\\\\\\\\"msg_init_error null check\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\n    st = aisoc_dbus_msg_unref(nullptr);\\\\\\\\n    TEST_CHECK(st == AISOC_DBUS_ERR_NULL_PTR, \\\\\\\\\\\\\\\"msg_unref null check\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\n    st = aisoc_dbus_msg_append_byte(nullptr, 0);\\\\\\\\n    TEST_CHECK(st == AISOC_DBUS_ERR_NULL_PTR, \\\\\\\\\\\\\\\"append_byte null check\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\n    st = aisoc_dbus_msg_append_string(nullptr, nullptr);\\\\\\\\n    TEST_CHECK(st == AISOC_DBUS_ERR_NULL_PTR, \\\\\\\\\\\\\\\"append_string null check\\\\\\\\\\\\\\\");\\\\\\\\n    return true;\\\\\\\\n}\\\\\\\\n\\\\\\\\nstatic bool test_guard_server() {\\\\\\\\n    aisoc_dbus_status_t st = aisoc_dbus_register_interface(nullptr, nullptr);\\\\\\\\n    TEST_CHECK(st == AISOC_DBUS_ERR_NULL_PTR, \\\\\\\\\\\\\\\"register_interface null check\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\n    st = aisoc_dbus_subscribe_signal(nullptr, nullptr);\\\\\\\\n    TEST_CHECK(st == AISOC_DBUS_ERR_NULL_PTR, \\\\\\\\\\\\\\\"subscribe_signal null check\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\n    st = aisoc_dbus_dispatch_once(nullptr, 0, nullptr);\\\\\\\\n    TEST_CHECK(st == AISOC_DBUS_ERR_NULL_PTR, \\\\\\\\\\\\\\\"dispatch_once null check\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\n    st = aisoc_dbus_flush(nullptr);\\\\\\\\n    TEST_CHECK(st == AISOC_DBUS_ERR_NULL_PTR, \\\\\\\\\\\\\\\"flush null check\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\n    st = aisoc_dbus_call_method(nullptr, nullptr, nullptr, nullptr);\\\\\\\\n    TEST_CHECK(st == AISOC_DBUS_ERR_NULL_PTR, \\\\\\\\\\\\\\\"call_method null check\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\n    st = aisoc_dbus_send_message(nullptr, nullptr);\\\\\\\\n    TEST_CHECK(st == AISOC_DBUS_ERR_NULL_PTR, \\\\\\\\\\\\\\\"send_message null check\\\\\\\\\\\\\\\");\\\\\\\\n    return true;\\\\\\\\n}\\\\\\\\n\\\\\\\\n/* ========================================================================= */\\\\\\\\n/* 2. Unit Tests: Error Mappings                                             */\\\\\\\\n/* ========================================================================= */\\\\\\\\n\\\\\\\\nstatic bool test_error_forward() {\\\\\\\\n    aisoc_dbus_status_t st = AISOC_DBUS_ERR_INTERNAL;\\\\\\\\n    aisoc_dbus_status_from_name(AISOC_DBUS_ERR_NAME_NONE, &st);\\\\\\\\n    TEST_CHECK(st == AISOC_DBUS_OK, \\\\\\\\\\\\\\\"None error map\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\n    aisoc_dbus_status_from_name(AISOC_DBUS_ERR_NAME_TIMEOUT, &st);\\\\\\\\n    TEST_CHECK(st == AISOC_DBUS_ERR_TIMEOUT, \\\\\\\\\\\\\\\"Timeout error map\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\n    aisoc_dbus_status_from_name(AISOC_DBUS_ERR_NAME_INVALID_ARG, &st);\\\\\\\\n    TEST_CHECK(st == AISOC_DBUS_ERR_INVALID_PARAM, \\\\\\\\\\\\\\\"InvalidArgument error map\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\n    aisoc_dbus_status_from_name(AISOC_DBUS_ERR_NAME_BUSY, &st);\\\\\\\\n    TEST_CHECK(st == AISOC_DBUS_ERR_DEVICE_BUSY, \\\\\\\\\\\\\\\"DeviceBusy error map\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\n    aisoc_dbus_status_from_name(AISOC_DBUS_ERR_NAME_CRC, &st);\\\\\\\\n    TEST_CHECK(st == AISOC_DBUS_ERR_CRC_MISMATCH, \\\\\\\\\\\\\\\"CrcMismatch error map\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\n    aisoc_dbus_status_from_name(AISOC_DBUS_ERR_NAME_ESTOP, &st);\\\\\\\\n    TEST_CHECK(st == AISOC_DBUS_ERR_EMERGENCY_STOP, \\\\\\\\\\\\\\\"EmergencyStopped error map\\\\\\\\\\\\\\\");\\\\\\\\n    return true;\\\\\\\\n}\\\\\\\\n\\\\\\\\nstatic bool test_error_reverse() {\\\\\\\\n    const char* name = nullptr;\\\\\\\\n    aisoc_dbus_status_to_name(AISOC_DBUS_OK, &name);\\\\\\\\n    TEST_CHECK(strcmp(name, AISOC_DBUS_ERR_NAME_NONE) == 0, \\\\\\\\\\\\\\\"OK to name\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\n    aisoc_dbus_status_to_name(AISOC_DBUS_ERR_TIMEOUT, &name);\\\\\\\\n    TEST_CHECK(strcmp(name, AISOC_DBUS_ERR_NAME_TIMEOUT) == 0, \\\\\\\\\\\\\\\"Timeout to name\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\n    aisoc_dbus_status_to_name(AISOC_DBUS_ERR_INVALID_PARAM, &name);\\\\\\\\n    TEST_CHECK(strcmp(name, AISOC_DBUS_ERR_NAME_INVALID_ARG) == 0, \\\\\\\\\\\\\\\"Invalid to name\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\n    aisoc_dbus_status_to_name(AISOC_DBUS_ERR_DEVICE_BUSY, &name);\\\\\\\\n    TEST_CHECK(strcmp(name, AISOC_DBUS_ERR_NAME_BUSY) == 0, \\\\\\\\\\\\\\\"Busy to name\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\n    aisoc_dbus_status_to_name(AISOC_DBUS_ERR_EMERGENCY_STOP, &name);\\\\\\\\n    TEST_CHECK(strcmp(name, AISOC_DBUS_ERR_NAME_ESTOP) == 0, \\\\\\\\\\\\\\\"Estop to name\\\\\\\\\\\\\\\");\\\\\\\\n    return true;\\\\\\\\n}\\\\\\\\n\\\\\\\\n/* ========================================================================= */\\\\\\\\n/* 3. Unit Tests: Message Type Serialization                                 */\\\\\\\\n/* ========================================================================= */\\\\\\\\n\\\\\\\\nstatic bool test_msg_types() {\\\\\\\\n    aisoc_dbus_method_call_t call;\\\\\\\\n    call.destination = \\\\\\\\\\\\\\\"org.aisoc.Test\\\\\\\\\\\\\\\";\\\\\\\\n    call.path = \\\\\\\\\\\\\\\"/org/aisoc/test\\\\\\\\\\\\\\\";\\\\\\\\n    call.interface_name = \\\\\\\\\\\\\\\"org.aisoc.TestInterface\\\\\\\\\\\\\\\";\\\\\\\\n    call.method_name = \\\\\\\\\\\\\\\"TestAll\\\\\\\\\\\\\\\";\\\\\\\\n\\\\\\\\n    aisoc_dbus_msg_t msg;\\\\\\\\n    aisoc_dbus_status_t st = aisoc_dbus_msg_init_call(&call, &msg);\\\\\\\\n    TEST_CHECK(st == AISOC_DBUS_OK, \\\\\\\\\\\\\\\"msg_init_call success\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\n    aisoc_dbus_msg_append_byte(&msg, 0xEF);\\\\\\\\n    aisoc_dbus_msg_append_bool(&msg, true);\\\\\\\\n    aisoc_dbus_msg_append_uint32(&msg, 654321U);\\\\\\\\n    aisoc_dbus_msg_append_int32(&msg, -54321);\\\\\\\\n    aisoc_dbus_msg_append_uint64(&msg, 0xAABBCCDDEEFF0011ULL);\\\\\\\\n    aisoc_dbus_msg_append_string(&msg, \\\\\\\\\\\\\\\"payload_test_val\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\n    aisoc_dbus_iter_t iter;\\\\\\\\n    aisoc_dbus_iter_init(&msg, &iter);\\\\\\\\n\\\\\\\\n    uint8_t byte_val = 0;\\\\\\\\n    bool b_val = false;\\\\\\\\n    uint32_t u32_val = 0;\\\\\\\\n    int32_t i32_val = 0;\\\\\\\\n    uint64_t u64_val = 0;\\\\\\\\n    const char* str_val = nullptr;\\\\\\\\n\\\\\\\\n    aisoc_dbus_iter_get_byte(&iter, &byte_val);\\\\\\\\n    aisoc_dbus_iter_get_bool(&iter, &b_val);\\\\\\\\n    aisoc_dbus_iter_get_uint32(&iter, &u32_val);\\\\\\\\n    aisoc_dbus_iter_get_int32(&iter, &i32_val);\\\\\\\\n    aisoc_dbus_iter_get_uint64(&iter, &u64_val);\\\\\\\\n    aisoc_dbus_iter_get_string(&iter, &str_val);\\\\\\\\n\\\\\\\\n    TEST_CHECK(byte_val == 0xEF, \\\\\\\\\\\\\\\"byte value\\\\\\\\\\\\\\\");\\\\\\\\n    TEST_CHECK(b_val == true, \\\\\\\\\\\\\\\"bool value\\\\\\\\\\\\\\\");\\\\\\\\n    TEST_CHECK(u32_val == 654321U, \\\\\\\\\\\\\\\"uint32 value\\\\\\\\\\\\\\\");\\\\\\\\n    TEST_CHECK(i32_val == -54321, \\\\\\\\\\\\\\\"int32 value\\\\\\\\\\\\\\\");\\\\\\\\n    TEST_CHECK(u64_val == 0xAABBCCDDEEFF0011ULL, \\\\\\\\\\\\\\\"uint64 value\\\\\\\\\\\\\\\");\\\\\\\\n    TEST_CHECK(str_val != nullptr && strcmp(str_val, \\\\\\\\\\\\\\\"payload_test_val\\\\\\\\\\\\\\\") == 0, \\\\\\\\\\\\\\\"string value\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\n    aisoc_dbus_msg_unref(&msg);\\\\\\\\n    return true;\\\\\\\\n}\\\\\\\\n\\\\\\\\n/* ========================================================================= */\\\\\\\\n/* 4. Cross-Process Server Handlers                                          */\\\\\\\\n/* ========================================================================= */\\\\\\\\n\\\\\\\\nstatic aisoc_dbus_status_t handle_fwd_query(\\\\\\\\n    const aisoc_dbus_msg_t* req,\\\\\\\\n    aisoc_dbus_msg_t*       reply,\\\\\\\\n    void*                   user_data\\\\\\\\n) {\\\\\\\\n    (void)user_data;\\\\\\\\n    aisoc_dbus_iter_t iter;\\\\\\\\n    aisoc_dbus_iter_init(req, &iter);\\\\\\\\n    uint8_t node = 0;\\\\\\\\n    uint32_t to_ms = 0;\\\\\\\\n    aisoc_dbus_iter_get_byte(&iter, &node);\\\\\\\\n    aisoc_dbus_iter_get_uint32(&iter, &to_ms);\\\\\\\\n\\\\\\\\n    if (node == 99) {\\\\\\\\n        return AISOC_DBUS_ERR_INVALID_PARAM;\\\\\\\\n    }\\\\\\\\n    if (node == 2 && to_ms == 50) {\\\\\\\\n        usleep(100000); /* 100ms triggers client 40ms timeout */\\\\\\\\n    }\\\\\\\\n    aisoc_dbus_msg_append_int32(reply, 0);\\\\\\\\n    aisoc_dbus_msg_append_uint32(reply, (node == 1) ? 1U : 2U);\\\\\\\\n    return AISOC_DBUS_OK;\\\\\\\\n}\\\\\\\\n\\\\\\\\nstatic aisoc_dbus_status_t handle_fwd_port(\\\\\\\\n    const aisoc_dbus_msg_t* req,\\\\\\\\n    aisoc_dbus_msg_t*       reply,\\\\\\\\n    void*                   user_data\\\\\\\\n) {\\\\\\\\n    (void)req;\\\\\\\\n    (void)user_data;\\\\\\\\n    aisoc_dbus_msg_append_bool(reply, true);\\\\\\\\n    aisoc_dbus_msg_append_string(reply, \\\\\\\\\\\\\\\"/dev/ttyUSB0\\\\\\\\\\\\\\\");\\\\\\\\n    aisoc_dbus_msg_append_uint64(reply, 1042ULL);\\\\\\\\n    aisoc_dbus_msg_append_uint64(reply, 1040ULL);\\\\\\\\n    return AISOC_DBUS_OK;\\\\\\\\n}\\\\\\\\n\\\\\\\\nstatic aisoc_dbus_status_t handle_fwd_estop(\\\\\\\\n    const aisoc_dbus_msg_t* req,\\\\\\\\n    aisoc_dbus_msg_t*       reply,\\\\\\\\n    void*                   user_data\\\\\\\\n) {\\\\\\\\n    (void)user_data;\\\\\\\\n    aisoc_dbus_iter_t iter;\\\\\\\\n    aisoc_dbus_iter_init(req, &iter);\\\\\\\\n    uint8_t reason = 0;\\\\\\\\n    aisoc_dbus_iter_get_byte(&iter, &reason);\\\\\\\\n\\\\\\\\n    aisoc_dbus_msg_append_int32(reply, 0);\\\\\\\\n    if (reason == 255) {\\\\\\\\n        g_server_running = false;\\\\\\\\n    }\\\\\\\\n    return AISOC_DBUS_OK;\\\\\\\\n}\\\\\\\\n\\\\\\\\nstatic aisoc_dbus_status_t handle_dev_sample(\\\\\\\\n    const aisoc_dbus_msg_t* req,\\\\\\\\n    aisoc_dbus_msg_t*       reply,\\\\\\\\n    void*                   user_data\\\\\\\\n) {\\\\\\\\n    (void)user_data;\\\\\\\\n    aisoc_dbus_iter_t iter;\\\\\\\\n/**\\\\\\\\n * @file aisoc_dbus_core.cpp\\\\\\\\n * @brief D-Bus Connection Management and Core Bus Lifecycle\\\\\\\\n * @details Conforms to:\\\\\\\\n *          - ICD-VMWARE-SOC-TWIN-20261029 (Rev 2)\\\\\\\\n *          - project-control/.agents/rules/c_cpp_coding_standard.md\\\\\\\\n * Task ID: TWIN-06\\\\\\\\n * Role: ENG-DBUS\\\\\\\\n */\\\\\\\\n\\\\\\\\n#include \\\\\\\\\\\\\\\"aisoc_dbus.h\\\\\\\\\\\\\\\"\\\\\\\\n#include \\\\\\\\\\\\\\\"aisoc_dbus_internal.h\\\\\\\\\\\\\\\"\\\\\\\\n#include <cstring>\\\\\\\\n\\\\\\\\naisoc_dbus_status_t aisoc_dbus_map_dbus_error(\\\\\\\\n    const DBusError* d_err\\\\\\\\n) {\\\\\\\\n    if (d_err == nullptr) {\\\\\\\\n        return AISOC_DBUS_ERR_NULL_PTR;\\\\\\\\n    }\\\\\\\\n    if (!dbus_error_is_set(d_err)) {\\\\\\\\n        return AISOC_DBUS_OK;\\\\\\\\n    }\\\\\\\\n    const char* n = d_err->name ? d_err->name : \\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\";\\\\\\\\n    if (strcmp(n, DBUS_ERROR_NO_REPLY) == 0 ||\\\\\\\\n        strcmp(n, DBUS_ERROR_TIMEOUT) == 0) {\\\\\\\\n        return AISOC_DBUS_ERR_TIMEOUT;\\\\\\\\n    }\\\\\\\\n    if (strcmp(n, DBUS_ERROR_ACCESS_DENIED) == 0 ||\\\\\\\\n        strcmp(n, DBUS_ERROR_AUTH_FAILED) == 0) {\\\\\\\\n        return AISOC_DBUS_ERR_PERMISSION_DENIED;\\\\\\\\n    }\\\\\\\\n    if (strcmp(n, DBUS_ERROR_DISCONNECTED) == 0) {\\\\\\\\n        return AISOC_DBUS_ERR_DISCONNECTED;\\\\\\\\n    }\\\\\\\\n    aisoc_dbus_status_t st = AISOC_DBUS_ERR_INTERNAL;\\\\\\\\n    aisoc_dbus_status_from_name(n, &st);\\\\\\\\n    return st;\\\\\\\\n}\\\\\\\\n\\\\\\\\nstatic DBusConnection* aisoc_dbus_open_connection(\\\\\\\\n    const aisoc_dbus_conn_config_t* config,\\\\\\\\n    DBusError*                      d_err\\\\\\\\n) {\\\\\\\\n    DBusConnection* c = nullptr;\\\\\\\\n    if (config->custom_address != nullptr) {\\\\\\\\n        c = dbus_connection_open_private(config->custom_address, d_err);\\\\\\\\n        if (c != nullptr) {\\\\\\\\n            dbus_bool_t reg_ok = dbus_bus_register(c, d_err);\\\\\\\\n            if (!reg_ok) {\\\\\\\\n                dbus_connection_close(c);\\\\\\\\n                dbus_connection_unref(c);\\\\\\\\n                c = nullptr;\\\\\\\\n            }\\\\\\\\n        }\\\\\\\\n    } else {\\\\\\\\n        DBusBusType btype = DBUS_BUS_SESSION;\\\\\\\\n        if (config->bus_type == AISOC_DBUS_BUS_SYSTEM) {\\\\\\\\n            btype = DBUS_BUS_SYSTEM;\\\\\\\\n        }\\\\\\\\n        c = dbus_bus_get_private(btype, d_err);\\\\\\\\n    }\\\\\\\\n    return c;\\\\\\\\n}\\\\\\\\n\\\\\\\\naisoc_dbus_status_t aisoc_dbus_conn_init(\\\\\\\\n    const aisoc_dbus_conn_config_t* config,\\\\\\\\n    aisoc_dbus_conn_t*              conn\\\\\\\\n) {\\\\\\\\n    if (config == nullptr || conn == nullptr) {\\\\\\\\n        return AISOC_DBUS_ERR_NULL_PTR;\\\\\\\\n    }\\\\\\\\n    memset(conn, 0, sizeof(*conn));\\\\\\\\n\\\\\\\\n    DBusError d_err;\\\\\\\\n    dbus_error_init(&d_err);\\\\\\\\n    DBusConnection* raw_conn = aisoc_dbus_open_connection(config, &d_err);\\\\\\\\n    if (raw_conn == nullptr) {\\\\\\\\n        aisoc_dbus_status_t err_st = aisoc_dbus_map_dbus_error(&d_err);\\\\\\\\n        dbus_error_free(&d_err);\\\\\\\\n        return err_st;\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    dbus_bool_t exit_mode = config->exit_on_disconnect ? TRUE : FALSE;\\\\\\\\n    dbus_connection_set_exit_on_disconnect(raw_conn, exit_mode);\\\\\\\\n\\\\\\\\n    conn->conn = raw_conn;\\\\\\\\n    conn->is_connected = true;\\\\\\\\n    const char* uniq = dbus_bus_get_unique_name(raw_conn);\\\\\\\\n    if (uniq != nullptr) {\\\\\\\\n        strncpy(conn->unique_name, uniq, sizeof(conn->unique_name) - 1U);\\\\\\\\n    }\\\\\\\\n    dbus_connection_add_filter(raw_conn, aisoc_dbus_internal_filter, conn, nullptr);\\\\\\\\n    return AISOC_DBUS_OK;\\\\\\\\n}\\\\\\\\n\\\\\\\\naisoc_dbus_status_t aisoc_dbus_conn_close(\\\\\\\\n    aisoc_dbus_conn_t* conn\\\\\\\\n) {\\\\\\\\n    if (conn == nullptr) {\\\\\\\\n        return AISOC_DBUS_ERR_NULL_PTR;\\\\\\\\n    }\\\\\\\\n    if (conn->conn != nullptr) {\\\\\\\\n        dbus_connection_remove_filter(conn->conn, aisoc_dbus_internal_filter, conn);\\\\\\\\n        dbus_connection_close(conn->conn);\\\\\\\\n        dbus_connection_unref(conn->conn);\\\\\\\\n        conn->conn = nullptr;\\\\\\\\n    }\\\\\\\\n    conn->is_connected = false;\\\\\\\\n    return AISOC_DBUS_OK;\\\\\\\\n}\\\\\\\\n\\\\\\\\naisoc_dbus_status_t aisoc_dbus_request_name(\\\\\\\\n    aisoc_dbus_conn_t* conn,\\\\\\\\n    const char*        name,\\\\\\\\n    bool               replace_existing\\\\\\\\n) {\\\\\\\\n    if (conn == nullptr || name == nullptr) {\\\\\\\\n        return AISOC_DBUS_ERR_NULL_PTR;\\\\\\\\n    }\\\\\\\\n    if (conn->conn == nullptr || !conn->is_connected) {\\\\\\\\n        return AISOC_DBUS_ERR_DISCONNECTED;\\\\\\\\n    }\\\\\\\\n    uint32_t flags = DBUS_NAME_FLAG_DO_NOT_QUEUE;\\\\\\\\n    if (replace_existing) {\\\\\\\\n        flags = flags | DBUS_NAME_FLAG_REPLACE_EXISTING;\\\\\\\\n    }\\\\\\\\n    DBusError d_err;\\\\\\\\n    dbus_error_init(&d_err);\\\\\\\\n    int res = dbus_bus_request_name(conn->conn, name, flags, &d_err);\\\\\\\\n    if (dbus_error_is_set(&d_err)) {\\\\\\\\n        aisoc_dbus_status_t st = aisoc_dbus_map_dbus_error(&d_err);\\\\\\\\n        dbus_error_free(&d_err);\\\\\\\\n        return st;\\\\\\\\n    }\\\\\\\\n    conn->is_server = true;\\\\\\\\n    if (res == DBUS_REQUEST_NAME_REPLY_PRIMARY_OWNER ||\\\\\\\\n        res == DBUS_REQUEST_NAME_REPLY_ALREADY_OWNER) {\\\\\\\\n        return AISOC_DBUS_OK;\\\\\\\\n    }\\\\\\\\n    return AISOC_DBUS_ERR_NAME_TAKEN;\\\\\\\\n}\\\\\\\\n\\\\\\\\naisoc_dbus_status_t aisoc_dbus_release_name(\\\\\\\\n    aisoc_dbus_conn_t* conn,\\\\\\\\n    const char*        name\\\\\\\\n) {\\\\\\\\n    if (conn == nullptr || name == nullptr) {\\\\\\\\n        return AISOC_DBUS_ERR_NULL_PTR;\\\\\\\\n    }\\\\\\\\n    if (conn->conn == nullptr || !conn->is_connected) {\\\\\\\\n        return AISOC_DBUS_ERR_DISCONNECTED;\\\\\\\\n    }\\\\\\\\n    DBusError d_err;\\\\\\\\n    dbus_error_init(&d_err);\\\\\\\\n    int res = dbus_bus_release_name(conn->conn, name, &d_err);\\\\\\\\n    if (dbus_error_is_set(&d_err)) {\\\\\\\\n        aisoc_dbus_status_t st = aisoc_dbus_map_dbus_error(&d_err);\\\\\\\\n        dbus_error_free(&d_err);\\\\\\\\n        return st;\\\\\\\\n    }\\\\\\\\n    if (res == DBUS_RELEASE_NAME_REPLY_RELEASED) {\\\\\\\\n        return AISOC_DBUS_OK;\\\\\\\\n    }\\\\\\\\n    return AISOC_DBUS_ERR_INVALID_PARAM;\\\\\\\\n}\\\\\\\\n\\\\\\\\naisoc_dbus_status_t aisoc_dbus_is_connected(\\\\\\\\n    const aisoc_dbus_conn_t* conn,\\\\\\\\n    bool*                    out_connected\\\\\\\\n) {\\\\\\\\n    if (conn == nullptr || out_connected == nullptr) {\\\\\\\\n        return AISOC_DBUS_ERR_NULL_PTR;\\\\\\\\n    }\\\\\\\\n    const bool has_handle = (conn->conn != nullptr);\\\\\\\\n    const bool flag_on = conn->is_connected;\\\\\\\\n    if (!has_handle || !flag_on) {\\\\\\\\n        *out_connected = false;\\\\\\\\n        return AISOC_DBUS_OK;\\\\\\\\n    }\\\\\\\\n    dbus_bool_t ok = dbus_connection_get_is_connected(conn->conn);\\\\\\\\n    *out_connected = (ok != FALSE);\\\\\\\\n    return AISOC_DBUS_OK;\\\\\\\\n}\\\\\\\\n\\\\\\\\naisoc_dbus_status_t aisoc_dbus_flush(\\\\\\\\n    aisoc_dbus_conn_t* conn\\\\\\\\n) {\\\\\\\\n    if (conn == nullptr) {\\\\\\\\n        return AISOC_DBUS_ERR_NULL_PTR;\\\\\\\\n    }\\\\\\\\n    if (conn->conn == nullptr || !conn->is_connected) {\\\\\\\\n        return AISOC_DBUS_ERR_DISCONNECTED;\\\\\\\\n    }\\\\\\\\n    dbus_connection_flush(conn->conn);\\\\\\\\n    return AISOC_DBUS_OK;\\\\\\\\n}\\\\\\\\n\\\\\\\\naisoc_dbus_status_t aisoc_dbus_dispatch_once(\\\\\\\\n    aisoc_dbus_conn_t* conn,\\\\\\\\n    int32_t            timeout_ms,\\\\\\\\n    bool*              out_dispatched\\\\\\\\n) {\\\\\\\\n    if (conn == nullptr || out_dispatched == nullptr) {\\\\\\\\n        return AISOC_DBUS_ERR_NULL_PTR;\\\\\\\\n    }\\\\\\\\n    *out_dispatched = false;\\\\\\\\n    if (conn->conn == nullptr || !conn->is_connected) {\\\\\\\\n        return AISOC_DBUS_ERR_DISCONNECTED;\\\\\\\\n    }\\\\\\\\n    int timeout = (timeout_ms < 0) ? 0 : timeout_ms;\\\\\\\\n    dbus_bool_t has_traffic = dbus_connection_read_write(conn->conn, timeout);\\\\\\\\n    if (!has_traffic) {\\\\\\\\n        conn->is_connected = false;\\\\\\\\n        return AISOC_DBUS_ERR_DISCONNECTED;\\\\\\\\n    }\\\\\\\\n    DBusDispatchStatus st = dbus_connection_dispatch(conn->conn);\\\\\\\\n    *out_dispatched = (st == DBUS_DISPATCH_DATA_REMAINS);\\\\\\\\n    return AISOC_DBUS_OK;\\\\\\\\n}\\\\\\\\n/**\\\\\\\\n * @file aisoc_dbus_server.cpp\\\\\\\\n * @brief D-Bus Server Object Registration, Signal Subscription and Dispatching\\\\\\\\n * @details Conforms to:\\\\\\\\n *          - ICD-VMWARE-SOC-TWIN-20261029 (Rev 2)\\\\\\\\n *          - dbus_interfaces.xml (v2.0)\\\\\\\\n *          - project-control/.agents/rules/c_cpp_coding_standard.md\\\\\\\\n